INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss ich hier manuell jeden Code testen?', 2, '[{"text": "Nein", "correct": true, "because": "Continuous Integration automatisiert"}, {"text": "Ja", "correct": false, "because": "Tests laufen regelmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praxis sorgt für häufige Code-Integration?', 3, '[{"text": "Continuous Integration", "correct": true, "because": "Regelmäßige Merges"}, {"text": "Continuous Deployment", "correct": false, "because": "Fokus auf Auslieferung"}, {"text": "Infrastruktur als Code", "correct": false, "because": "Infrastrukturverwaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken steigern die Effizienz?', 5, '[{"text": "Continuous Integration", "correct": true, "because": "Automatisierte Tests"}, {"text": "Continuous Deployment", "correct": true, "because": "Schnelle Bereitstellung"}, {"text": "Manuelle Deployments", "correct": false, "because": "Langsamer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IaC verwaltet Infrastruktur. b) CI ist nur für große Teams.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CI für alle Teams"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Praktiken?', 4, '[{"text": "Continuous Integration", "correct": false, "because": "Kern für Qualität"}, {"text": "Infrastruktur als Code", "correct": false, "because": "Skalierung ermöglichen"}, {"text": "Manuelle Tests", "correct": true, "because": "Automatisierung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier selten deploye?', 2, '[{"text": "Nein", "correct": true, "because": "Continuous Deployment häufig"}, {"text": "Ja", "correct": false, "because": "Regelmäßige Auslieferung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für automatische Auslieferung?', 3, '[{"text": "Continuous Deployment", "correct": true, "because": "Automatisiert Deployments"}, {"text": "Continuous Integration", "correct": false, "because": "Fokus auf Tests"}, {"text": "Infrastruktur als Code", "correct": false, "because": "Infrastrukturverwaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken fördern Skalierbarkeit?', 5, '[{"text": "Infrastruktur als Code", "correct": true, "because": "Automatisierte Umgebungen"}, {"text": "Continuous Deployment", "correct": true, "because": "Schnelle Anpassung"}, {"text": "Manuelle Serverkonfiguration", "correct": false, "because": "Nicht skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) CI testet regelmäßig. b) CD ist nur für Tests. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CD für Deployment"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Continuous Integration", "correct": false, "because": "Qualität sichern"}, {"text": "Infrastruktur als Code", "correct": false, "because": "Skalierung fördern"}, {"text": "Manuelle Bereitstellung", "correct": true, "because": "Automatisierung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist IaC nur für kleine Projekte?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierbar für alle Größen"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken sichern schnelle Lieferung?', 4, '[{"text": "Continuous Deployment", "correct": true, "because": "Automatische Auslieferung"}, {"text": "Continuous Integration", "correct": true, "because": "Schnelle Fehlererkennung"}, {"text": "Langsame Tests", "correct": false, "because": "Automatisierung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier manuell konfiguriere. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "IaC automatisiert Infrastruktur"}, {"text": "Ja", "correct": false, "because": "Code-basierte Verwaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für schnelle Tests?', 3, '[{"text": "Continuous Integration", "correct": true, "because": "Automatisierte Tests"}, {"text": "Manuelle Prüfungen", "correct": false, "because": "Zeitaufwendig"}, {"text": "Seltene Deployments", "correct": false, "because": "Häufigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CD liefert oft. b) IaC ist nur für Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IaC für Infrastruktur"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile haben diese Praktiken?', 5, '[{"text": "Schnelle Auslieferung", "correct": true, "because": "CD automatisiert"}, {"text": "Wiederholbarkeit", "correct": true, "because": "IaC standardisiert"}, {"text": "Manuelle Eingriffe", "correct": false, "because": "Automatisierung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Continuous Integration", "correct": false, "because": "Qualität sichern"}, {"text": "Continuous Deployment", "correct": false, "because": "Lieferung fördern"}, {"text": "Manuelle Konfiguration", "correct": true, "because": "IaC übernimmt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist CI nur für Entwickler?', 3, '[{"text": "Nein", "correct": true, "because": "Teamübergreifend nützlich"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier selten teste?', 2, '[{"text": "Nein", "correct": true, "because": "CI testet regelmäßig"}, {"text": "Ja", "correct": false, "because": "Automatisierte Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praxis wähle ich für skalierbare Umgebungen?', 4, '[{"text": "Infrastruktur als Code", "correct": true, "because": "Automatisiert Infrastruktur"}, {"text": "Manuelle Server", "correct": false, "because": "Nicht skalierbar"}, {"text": "Seltene Tests", "correct": false, "because": "CI zentral"}]');
